export const ORIGINAL_AVATAR_ASSET_COUNT147=223;
export function originalLayerPath147(s,slot){
 if(slot==='body')return `avatars/original/body/f_${s.body+1}.png`;
 if(slot==='glasses'&&!s.glasses)return null;
 const [category,prefix]=({shirt:['clothing','c'],mouth:['mouth','m'],eyes:['eyes','e'],hair:['hair','h'],glasses:['accessories-g','g']})[slot];
 const base=s.body<2?`fitted/f_${s.body+1}`:'original';
 return `avatars/${base}/${category}/${prefix}_${s[slot]+1}.png`;
}
export function originalLayer147(s,slot){const path=originalLayerPath147(s,slot);if(!path)return '';if(!ART[path])throw Error('Falta una capa del avatar: '+path);return ART[path];}
